import { useState, useMemo } from 'react';
import { YearlySchedule } from '../types';

interface LoanTableProps {
  schedule?: YearlySchedule[];
}

export default function LoanTable({ schedule = [] }: LoanTableProps) {
  const [displayMode, setDisplayMode] = useState<'all' | 'five-years'>('all');

  const filteredSchedule = useMemo(() => {
    if (displayMode === 'all') {
      return schedule;
    }
    const total = schedule.length;
    return schedule.filter((item) => {
      // 1年目、5の倍数年、最終年（重複排除）
      return item.year === 1 || item.year % 5 === 0 || item.year === total;
    });
  }, [schedule, displayMode]);

  const handleDownloadCsv = () => {
    if (schedule.length === 0) return;

    const headers = [
      '返済年',
      '年間元金返済(円)',
      '年間利息支払(円)',
      '年間返済合計(円)',
      '年末ローン残高(円)',
      '累計返済総額(円)',
    ];

    const rows = schedule.map((item) => [
      `${item.year}年目`,
      item.yearlyPrincipal,
      item.yearlyInterest,
      item.yearlyPrincipal + item.yearlyInterest,
      item.remainingBalance,
      item.totalPaid,
    ]);

    const csvContent =
      '\uFEFF' +
      [headers.join(','), ...rows.map((row) => row.join(','))].join('\r\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'loan_repayment_schedule.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="card table-card">
      <div className="card-title">
        <span>年別返済シミュレーション表</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
          <button
            type="button"
            onClick={handleDownloadCsv}
            disabled={schedule.length === 0}
            title="CSV形式で全期間の返済表をダウンロード"
            style={{
              border: '1px solid var(--color-border)',
              background: 'var(--color-surface)',
              color: 'var(--color-text)',
              padding: '6px 12px',
              fontSize: '13px',
              fontWeight: 600,
              borderRadius: 'var(--radius-md)',
              cursor: schedule.length === 0 ? 'not-allowed' : 'pointer',
              transition: 'all 0.2s ease',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '4px',
            }}
          >
            <span>↓ CSV保存</span>
          </button>
          <div className="tab-btn-group">
            <button
              type="button"
              className={displayMode === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setDisplayMode('all')}
            >
              全期間
            </button>
            <button
              type="button"
              className={displayMode === 'five-years' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setDisplayMode('five-years')}
            >
              5年刻み
            </button>
          </div>
        </div>
      </div>

      <div className="table-wrapper">
        <table className="schedule-table">
          <thead>
            <tr>
              <th>返済年</th>
              <th>年間元金返済</th>
              <th>年間利息支払</th>
              <th>年間返済合計</th>
              <th>年末ローン残高</th>
              <th>累計返済総額</th>
            </tr>
          </thead>
          <tbody>
            {filteredSchedule.length === 0 ? (
              <tr>
                <td colSpan={6} style={{ textAlign: 'center', padding: '24px' }}>
                  シミュレーションデータがありません
                </td>
              </tr>
            ) : (
              filteredSchedule.map((row) => {
                const yearTotalPayment = row.yearlyPrincipal + row.yearlyInterest;
                const isHighlight = row.year % 5 === 0;

                return (
                  <tr
                    key={row.year}
                    className={isHighlight ? 'highlight-row' : undefined}
                  >
                    <td>
                      <strong>{row.year}年目</strong>
                    </td>
                    <td>
                      <span className="num-val">{row.yearlyPrincipal.toLocaleString()}</span>
                      <span className="unit-label" style={{ fontSize: '11px', marginLeft: '3px', color: 'var(--color-text-secondary)' }}>円</span>
                    </td>
                    <td style={{ color: 'var(--color-danger)' }}>
                      <span className="num-val">{row.yearlyInterest.toLocaleString()}</span>
                      <span className="unit-label" style={{ fontSize: '11px', marginLeft: '3px', color: 'var(--color-text-secondary)' }}>円</span>
                    </td>
                    <td>
                      <strong>
                        <span className="num-val">{yearTotalPayment.toLocaleString()}</span>
                        <span className="unit-label" style={{ fontSize: '11px', marginLeft: '3px', color: 'var(--color-text-secondary)' }}>円</span>
                      </strong>
                    </td>
                    <td>
                      <strong style={{ color: 'var(--color-primary)' }}>
                        <span className="num-val">{row.remainingBalance.toLocaleString()}</span>
                        <span className="unit-label" style={{ fontSize: '11px', marginLeft: '3px', color: 'var(--color-text-secondary)' }}>円</span>
                      </strong>
                    </td>
                    <td>
                      <span className="num-val">{row.totalPaid.toLocaleString()}</span>
                      <span className="unit-label" style={{ fontSize: '11px', marginLeft: '3px', color: 'var(--color-text-secondary)' }}>円</span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { LoanParams } from './types';
import { calculateLoan } from './utils/loanCalculator';
import LoanChart from './components/LoanChart';
import LoanTable from './components/LoanTable';

// 入力範囲定数の一元管理
const LIMITS = {
  PRINCIPAL: { MIN: 100, MAX: 20000, STEP_NUMBER: 50, STEP_SLIDER: 50 },
  RATE: { MIN: 0.01, MAX: 15.0, STEP_NUMBER: 0.01, STEP_SLIDER: 0.05 },
  YEARS: { MIN: 1, MAX: 50, STEP: 1 },
  BONUS: { MIN: 0, MAX: 150, STEP_NUMBER: 5, STEP_SLIDER: 1 },
} as const;

export default function App() {
  // 借入額（万円単位で保持し、計算時に円に変換）
  const [principalManYen, setPrincipalManYen] = useState<number>(3500);
  // 年利（%）
  const [interestRate, setInterestRate] = useState<number>(0.7);
  // 返済期間（年）
  const [years, setYears] = useState<number>(35);
  // 返済方式
  const [method, setMethod] = useState<'equal-payment' | 'equal-principal'>('equal-payment');
  // ボーナス加算額（1回あたり・万円）
  const [bonusManYen, setBonusManYen] = useState<number>(0);

  // 計算パラメータ作成
  const loanParams: LoanParams = useMemo(() => {
    return {
      principal: principalManYen * 10000,
      interestRate: interestRate,
      years: years,
      method: method,
      bonusAmount: bonusManYen * 10000,
    };
  }, [principalManYen, interestRate, years, method, bonusManYen]);

  // ローン計算の実行
  const result = useMemo(() => {
    return calculateLoan(loanParams);
  }, [loanParams]);

  // 借入額入力ハンドラ
  const handlePrincipalChange = (val: number) => {
    const clamped = Math.max(
      LIMITS.PRINCIPAL.MIN,
      Math.min(LIMITS.PRINCIPAL.MAX, isNaN(val) ? LIMITS.PRINCIPAL.MIN : val)
    );
    setPrincipalManYen(clamped);
  };

  // 金利入力ハンドラ
  const handleRateChange = (val: number) => {
    const clamped = Math.max(
      LIMITS.RATE.MIN,
      Math.min(LIMITS.RATE.MAX, isNaN(val) ? LIMITS.RATE.MIN : val)
    );
    setInterestRate(Math.round(clamped * 100) / 100);
  };

  // 返済年数変更ハンドラ
  const handleYearsChange = (val: number) => {
    const clamped = Math.max(
      LIMITS.YEARS.MIN,
      Math.min(LIMITS.YEARS.MAX, isNaN(val) ? LIMITS.YEARS.MIN : val)
    );
    setYears(clamped);
  };

  // ボーナス返済額変更ハンドラ
  const handleBonusChange = (val: number) => {
    const clamped = Math.max(
      LIMITS.BONUS.MIN,
      Math.min(LIMITS.BONUS.MAX, isNaN(val) ? LIMITS.BONUS.MIN : val)
    );
    setBonusManYen(clamped);
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <span className="header-badge">Mortgage Calculator</span>
        <h1>住宅ローン返済シミュレーター</h1>
        <p>
          借入額・金利・返済年数から毎月の返済額・返済総額・利息内訳を即座に計算し、年別推移をグラフと表で確認できます。
        </p>
      </header>

      <div className="calculator-grid">
        {/* 入力フォームカード */}
        <section className="card">
          <h2 className="card-title">ローン借入条件の設定</h2>

          {/* 借入金額 */}
          <div className="form-group">
            <div className="label-row">
              <label htmlFor="principal-input">借入希望額</label>
              <span style={{ fontSize: '12px', color: 'var(--color-text-secondary)' }}>
                {principalManYen >= 10000
                  ? `${Math.floor(principalManYen / 10000)}億${
                      principalManYen % 10000 > 0 ? (principalManYen % 10000) + '万' : ''
                    }円`
                  : `${principalManYen.toLocaleString()}万円`}
              </span>
            </div>
            <div className="slider-input-group">
              <div className="input-unit">
                <input
                  id="principal-input"
                  type="number"
                  className="number-input"
                  min={LIMITS.PRINCIPAL.MIN}
                  max={LIMITS.PRINCIPAL.MAX}
                  step={LIMITS.PRINCIPAL.STEP_NUMBER}
                  value={principalManYen}
                  onChange={(e) => handlePrincipalChange(Number(e.target.value))}
                />
                <span>万円</span>
              </div>
              <input
                type="range"
                className="slider"
                min={LIMITS.PRINCIPAL.MIN}
                max={LIMITS.PRINCIPAL.MAX}
                step={LIMITS.PRINCIPAL.STEP_SLIDER}
                value={principalManYen}
                onChange={(e) => handlePrincipalChange(Number(e.target.value))}
              />
            </div>
          </div>

          {/* 年利 */}
          <div className="form-group">
            <div className="label-row">
              <label htmlFor="rate-input">借入金利（年利）</label>
              <span style={{ fontSize: '12px', color: 'var(--color-text-secondary)' }}>
                {interestRate.toFixed(2)} %
              </span>
            </div>
            <div className="slider-input-group">
              <div className="input-unit">
                <input
                  id="rate-input"
                  type="number"
                  className="number-input"
                  min={LIMITS.RATE.MIN}
                  max={LIMITS.RATE.MAX}
                  step={LIMITS.RATE.STEP_NUMBER}
                  value={interestRate}
                  onChange={(e) => handleRateChange(Number(e.target.value))}
                />
                <span>%</span>
              </div>
              <input
                type="range"
                className="slider"
                min={LIMITS.RATE.MIN}
                max={LIMITS.RATE.MAX}
                step={LIMITS.RATE.STEP_SLIDER}
                value={interestRate}
                onChange={(e) => handleRateChange(Number(e.target.value))}
              />
            </div>
          </div>

          {/* 返済年数 */}
          <div className="form-group">
            <div className="label-row">
              <label htmlFor="years-input">返済期間</label>
              <span style={{ fontSize: '12px', color: 'var(--color-text-secondary)' }}>
                {years} 年（全{years * 12}回）
              </span>
            </div>
            <div className="slider-input-group">
              <div className="input-unit">
                <input
                  id="years-input"
                  type="number"
                  className="number-input"
                  min={LIMITS.YEARS.MIN}
                  max={LIMITS.YEARS.MAX}
                  step={LIMITS.YEARS.STEP}
                  value={years}
                  onChange={(e) => handleYearsChange(Number(e.target.value))}
                />
                <span>年</span>
              </div>
              <input
                type="range"
                className="slider"
                min={LIMITS.YEARS.MIN}
                max={LIMITS.YEARS.MAX}
                step={LIMITS.YEARS.STEP}
                value={years}
                onChange={(e) => handleYearsChange(Number(e.target.value))}
              />
            </div>
          </div>

          {/* 返済方式 */}
          <div className="form-group">
            <div className="label-row">
              <label>返済方式</label>
            </div>
            <div className="radio-group">
              <label
                className={
                  method === 'equal-payment' ? 'radio-label active' : 'radio-label'
                }
              >
                <input
                  type="radio"
                  name="loan-method"
                  value="equal-payment"
                  checked={method === 'equal-payment'}
                  onChange={() => setMethod('equal-payment')}
                />
                <span>元利均等返済</span>
                <small style={{ fontSize: '11px', marginTop: '4px', opacity: 0.85 }}>
                  毎月の返済額が一定
                </small>
              </label>

              <label
                className={
                  method === 'equal-principal' ? 'radio-label active' : 'radio-label'
                }
              >
                <input
                  type="radio"
                  name="loan-method"
                  value="equal-principal"
                  checked={method === 'equal-principal'}
                  onChange={() => setMethod('equal-principal')}
                />
                <span>元金均等返済</span>
                <small style={{ fontSize: '11px', marginTop: '4px', opacity: 0.85 }}>
                  元金が一定・利息軽減
                </small>
              </label>
            </div>
          </div>

          {/* ボーナス返済加算額 */}
          <div className="form-group">
            <div className="label-row">
              <label htmlFor="bonus-input">ボーナス時加算返済（年2回・1回分）</label>
              <span style={{ fontSize: '12px', color: 'var(--color-text-secondary)' }}>
                {bonusManYen > 0 ? `${bonusManYen}万円 / 回` : '加算なし'}
              </span>
            </div>
            <div className="slider-input-group">
              <div className="input-unit">
                <input
                  id="bonus-input"
                  type="number"
                  className="number-input"
                  min={LIMITS.BONUS.MIN}
                  max={LIMITS.BONUS.MAX}
                  step={LIMITS.BONUS.STEP_NUMBER}
                  value={bonusManYen}
                  onChange={(e) => handleBonusChange(Number(e.target.value))}
                />
                <span>万円</span>
              </div>
              <input
                type="range"
                className="slider"
                min={LIMITS.BONUS.MIN}
                max={LIMITS.BONUS.MAX}
                step={LIMITS.BONUS.STEP_SLIDER}
                value={bonusManYen}
                onChange={(e) => handleBonusChange(Number(e.target.value))}
              />
            </div>
          </div>
        </section>

        {/* 計算結果表示・グラフ・テーブルエリア */}
        <section>
          {/* サマリーカード */}
          <div className="summary-grid">
            <div className="summary-card summary-card-primary">
              <div>
                <span className="summary-label">
                  {method === 'equal-principal' ? '毎月の返済目安（初月）' : '毎月の返済目安'}
                </span>
                <div className="summary-value">
                  {result.monthlyPayment.toLocaleString()}
                  <span style={{ fontSize: '16px', fontWeight: 600, marginLeft: '4px' }}>円</span>
                </div>
              </div>
              <div className="summary-subtext">
                {method === 'equal-principal' ? (
                  <>
                    初月: {result.monthlyPaymentMax?.toLocaleString() ?? result.monthlyPayment.toLocaleString()} 円 〜 最終月: {result.monthlyPaymentMin?.toLocaleString() ?? 0} 円
                    {bonusManYen > 0 ? ` (ボーナス月＋${bonusManYen}万円)` : ''}
                  </>
                ) : bonusManYen > 0 ? (
                  `※ボーナス月は＋${bonusManYen}万円`
                ) : (
                  '※毎月均等のお支払額'
                )}
              </div>
            </div>

            <div className="summary-card">
              <div>
                <span className="summary-label">総返済額（元金＋利息）</span>
                <div className="summary-value" style={{ color: 'var(--color-primary-dark)' }}>
                  {Math.round(result.totalPayment / 10000).toLocaleString()}
                  <span style={{ fontSize: '16px', fontWeight: 600, marginLeft: '4px' }}>万円</span>
                </div>
              </div>
              <div className="summary-subtext">
                実額: {result.totalPayment.toLocaleString()} 円
              </div>
            </div>

            <div className="summary-card">
              <div>
                <span className="summary-label">利息総支払額</span>
                <div className="summary-value" style={{ color: 'var(--color-danger)' }}>
                  {Math.round(result.totalInterest / 10000).toLocaleString()}
                  <span style={{ fontSize: '16px', fontWeight: 600, marginLeft: '4px' }}>万円</span>
                </div>
              </div>
              <div className="summary-subtext">
                借入元金の{' '}
                {((result.totalInterest / (principalManYen * 10000)) * 100 || 0).toFixed(1)} % 相当
              </div>
            </div>
          </div>

          {/* ローングラフ */}
          <LoanChart schedule={result.yearlySchedule} />

          {/* 返済年別テーブル */}
          <LoanTable schedule={result.yearlySchedule} />
        </section>
      </div>
    </div>
  );
}
